def get_int(prompt, min_val=None, max_val=None):
    """احصل على عدد صحيح صحيح من المستخدم، اختياريًا ضمن نطاق."""
    while True:
        try:
            value = int(input(prompt))
            if min_val is not None and value < min_val:
                raise ValueError(f"Must be at least {min_val}")
            if max_val is not None and value > max_val:
                raise ValueError(f"Must be at most {max_val}")
            return value
        except ValueError as e:
            print(f"  ✘ Invalid: {e}. Please try again.")

def get_float(prompt, min_val=None, max_val=None):
    """احصل على عدد عشري صحيح من المستخدم، اختياريًا ضمن نطاق."""
    while True:
        try:
            value = float(input(prompt))
            if min_val is not None and value < min_val:
                raise ValueError(f"Must be at least {min_val}")
            if max_val is not None and value > max_val:
                raise ValueError(f"Must be at most {max_val}")
            return value
        except ValueError as e:
            print(f"  ✘ Invalid: {e}. Please try again.")

def get_choice(prompt, options):
    """احصل على اختيار من قائمة خيارات مسموحة."""
    options_str = "/".join(options)
    while True:
        answer = input(f"{prompt} ({options_str}): ").strip().lower()
        if answer in [o.lower() for o in options]:
            return answer
        print(f"  ✘ Please choose from: {options_str}")

def get_yes_no(prompt):
    """احصل على إجابة نعم/لا — ترجع True لنعم، False للا."""
